arguments.script:
(async () => {
  const btn = document.querySelector('.login-button') || [...document.querySelectorAll('button')].find(b => b.textContent.replace(/\s/g,'').includes('登录'));
  if (!btn) return JSON.stringify({clicked:false, url: location.href});
  btn.click();
  await new Promise(r => setTimeout(r, 3000));
  const err = (document.querySelector('.el-message__content')||{}).textContent || null;
  return JSON.stringify({clicked:true, url: location.href, title: document.title, err});
})()

(async () => {
  // 抓验证码接口返回与输入框值，先只提交一次并读取登录接口响应
  const token = sessionStorage.getItem('captcha-uuid') || '';
  return JSON.stringify({uuid: token, allSession: Object.keys(sessionStorage), local: Object.keys(localStorage)});
})()

(async () => {
  const resp = await fetch('/api/v3.0/code', {method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({})});
  const j = await resp.json();
  return JSON.stringify({status: resp.status, code: j.code, uuid: j.uuid || (j.data && j.data.uuid) || null, keys: Object.keys(j), dataKeys: j.data ? Object.keys(j.data) : null});
})()

(async () => {
  const resp = await fetch('/api/v3.0/code', {method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({type:'math'})});
  const txt = await resp.text();
  return JSON.stringify({status: resp.status, head: txt.slice(0,200)});
})()

(async () => {
  // 对照：9002 直连同样 POST 带 body；也试 GET /api/v3.0/code
  const tries = {};
  const t1 = await fetch('/api/v3.0/code', {method:'POST', headers:{'Content-Type':'application/json'}, body: '{"type":"login"}'});
  tries.login = t1.status;
  const t2 = await fetch('/api/v3.0/code?timestamp=' + Date.now());
  tries.get = t2.status;
  return JSON.stringify(tries);
})()

